import React from "react";
import { MapContainer, TileLayer, Marker, Popup } from "react-leaflet";
import "leaflet/dist/leaflet.css";

function MapView({ filters, cnpj }) {
  const position = [-23.55052, -46.633308]; // Padrão SP

  return (
    <MapContainer center={position} zoom={6} style={{ height: "500px", width: "100%" }}>
      <TileLayer
        attribution='&copy; OpenStreetMap'
        url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
      />
      <Marker position={position}>
        <Popup>
          Revenda Exemplo <br />
          <a href={`https://waze.com/ul?ll=${position[0]},${position[1]}`}>Abrir no Waze</a>
        </Popup>
      </Marker>
    </MapContainer>
  );
}

export default MapView;
